const SceneDef *findSceneDef(const char *name) {
	for (const SceneDef *s = sceneDefs; s->name; s++)
		if (!scumm_stricmp(s->name, name))
			return s;
	return nullptr;
}

const AnimDef *findAnimDef(const SceneDef *scene, const char *name) {
	if (!scene || !scene->anims)
		return nullptr;
	for (const AnimDef *a = scene->anims; a->name; a++)
		if (!scumm_stricmp(a->name, name))
			return a;
	return nullptr;
}

const CursorEntry *findCursorTable(const char *name) {
	for (const NamedCursorTable *t = cursorTables; t->name; t++)
		if (!scumm_stricmp(t->name, name))
			return t->table;
	return nullptr;
}

